package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaZhDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_yamani_hajar" to DuaText("鲁肯·亚马尼 (Rukn Yamani) 和哈贾尔·阿斯瓦德 (Hajar Aswad) 之间", "我们的主，请赐予我们今世和后世的美好，并保护我们免受火的惩罚。", "在塔瓦夫，也门角和黑石之间。", "先知 ﷺ 在 tawaf 的这个地方背诵了这一点。"),
        "dua_safa_marwa" to DuaText("萨法和马尔瓦", "除了真主之外，没有人有权利被崇拜，独自一人，没有伴侣。统治权归他所有，赞美归他所有，他对万事都有能力。除安拉外，没有人有权受崇拜；他履行了他的诺言，帮助了他的仆人，并独自击败了同盟者。", "爬萨法并面向朝拜（三次）。", "先知 ﷺ 关于 Safa 和 Marwah 的 dhikr。"),
        "dua_arafah" to DuaText("阿拉法日最佳双人舞", "除了真主之外，没有人有权利被崇拜，独自一人，没有伴侣。统治权归他所有，赞美归他所有，他对万事都有能力。", "阿拉法日——最好的杜阿。", "最好的杜阿是阿拉法日的杜阿，最好的词是这些。"),
        "dua_takbeer_tashreeq" to DuaText("塔克比尔·塔什里克", "安拉是最伟大的，安拉是最伟大的。除真主外，别无上帝。安拉是最伟大的，安拉是最伟大的，一切赞美都归于安拉。", "从 9 Dhul-Hijjah 的晨礼到 13 Dhul-Hijjah 的晡礼期间的每次义务祈祷后。", "阿里和伊本·马斯乌德 (RA) 报道 — 根据哈纳菲派的说法，wajib。"),
        "dua_zamzam" to DuaText("喝渗渗泉", "安拉啊，我祈求您赐予有益的知识、丰富的供给和治愈各种疾病的方法。", "喝 Zamzam 时，可以随心所欲地调制 dua。", "Zamzam 是为了任何喝醉的目的（Ibn Majah 3062）。"),
        "dua_q_ma_khalaqta_batila" to DuaText("反思创作", "我们的主啊，您创造这一切并非徒然。荣耀归于您，请保护我们免受火焰的惩罚。", "反思天地创造者的杜阿。", "理解者的杜阿（ulul-albab）。"),
        "dua_q_sami_na_munadiyan" to DuaText("我们听到了信仰的召唤", "我们的主，我们听到一个呼唤信仰的人说“相信你的主”，我们就相信了。我们的主，宽恕我们的罪孽，消除我们的恶行，使我们与义人同死。", "为信仰而死的二重奏。", "宽恕和美好结局的二重唱。"),
        "dua_q_atina_ma_waadtana" to DuaText("兑现您的承诺", "我们的主，请赐予我们您通过您的使者所许诺的东西，并且不要在复活日让我们蒙羞。事实上，你并没有违背你的诺言。", "在复活日免遭耻辱。", "在后世寻求荣耀。"),
        "dua_q_israfana" to DuaText("原谅我们的过分行为", "我们的主，请宽恕我们的罪和我们在事务上的过激行为，使我们的脚步坚定，并帮助我们对抗不信的人。", "早期先知同伴的杜阿。", "代表坚定和宽恕的二重奏。"),
        "dua_q_jamiun_nas" to DuaText("你将聚集人类", "我们的主啊，您一定会在毫无疑问的一天聚集人类。确实，真主不会违背他的诺言。", "确认复活日的确定性。", "那些牢固地扎根于知识的人的二重奏。"),
        "dua_q_maash_shahidin" to DuaText("写下我们是见证人之一", "我们的主啊，我们已经相信了，所以请将我们写在见证人之中。", "那些认识真理并相信的人的杜阿。", "接受一个人的信仰的二重唱。"),
        "dua_q_la_tajalna_zalimin" to DuaText("不与不法之徒同在", "我们的主，不要将我们与作恶的人放在一起。", "阿拉夫人民的杜阿。", "逃避作恶者的命运。"),
        "dua_q_tawaffana_muslimin" to DuaText("作为穆斯林的耐心和死亡", "我们的主啊，请将耐心倾注在我们身上，让我们作为穆斯林死去。", "法老魔法师相信时的杜阿。", "考验中的忍耐，信心的终结。"),
        "dua_q_la_tajalna_fitnah" to DuaText("不是对压迫者的审判", "我们依靠安拉。我们的主，求你不要让我们受不义之人的审判，求你以你的怜悯拯救我们，使我们脱离不信道的人。", "穆萨人民的杜阿(AS)。", "拯救压迫者和压迫者的二人组。"),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua of Nuh (AS) 宽恕", "我的主啊，我向您寻求庇护，以免向您索要我不知道的事情。除非你原谅我并怜悯我，否则我将成为失败者之一。", "先知 Nuh (AS) 的悔罪二重奏。", "以正确的方式提问的教训。"),
        "dua_q_mudkhala_sidq" to DuaText("真理的入口与出口", "主啊，求你使我带着真理进入，带着真理出去，并从你自己赐予我支持的权柄。", "在进入新的任务、家庭或地点之前。", "dua 在迁徙期间向先知 ﷺ 教导。"),
        "dua_q_la_tadharni_fardan" to DuaText("Dua of Zakariya (AS) — 不要让我独自一人", "我的主啊，不要让我孤单，你是最好的继承人。", "对于那些寻找孩子的人。", "通过这个 dua 安拉授予了叶海亚 (AS)。"),
        "dua_q_munzalan_mubarakan" to DuaText("幸福的着陆点", "我的主，让我降落在一个受祝福的着陆点，你是那些着陆的人中最好的。", "当搬到新家或停在某个地方时——Nuh (AS) 的二音。", "在新的地方祝福的二人组。"),
        "dua_q_amanna_faghfir" to DuaText("我们相信，所以请原谅我们", "我们的主啊，我们已经相信了，所以请宽恕我们，怜悯我们，你是最仁慈的人。", "安拉正义仆人的杜阿。", "宽恕和仁慈的全面二重奏。"),
        "dua_q_isrif_jahannam" to DuaText("避免地狱的惩罚", "我们的主啊，请使我们远离地狱的惩罚；事实上，它的惩罚是始终如一的。确实，这是一个邪恶的定居点和住所。", "最仁慈者（'Ibad ar-Rahman）的仆人的杜阿。", "《古兰经》中的杜阿，表示逃离地狱的避难所。"),
        "dua_q_hab_li_hukman" to DuaText("易卜拉欣的杜阿 (AS) — 智慧和詹纳", "主啊，赐予我智慧，与正义者一起，赐我于后世的名号，使我成为极乐花园的继承人。", "祈求智慧、正义与天堂的陪伴。", "易卜拉欣的综合二重奏 (AS)。"),
        "dua_q_lut_najjini_ahli" to DuaText("Dua of Lut (AS) — 拯救我的家人", "主啊，请拯救我和我的家人免受他们所做之事（的后果）的影响。", "保护家人免受邪恶环境的侵害。", "保护家人免受邪恶侵害。"),
        "dua_q_sulaiman_awzini" to DuaText("苏莱曼杜阿 (AS) 致谢", "主啊，求你使我能够感谢你对我和我父母的恩惠，并行你所喜悦的正义之事，并以你的慈悲接纳我为你正义的仆人之一。", "拥有感恩祝福的能力。", "苏莱曼 (AS) 的感谢之情。"),
        "dua_q_musa_zalamtu" to DuaText("穆萨的杜阿 (AS) — 我委屈了自己", "主啊，我得罪了自己，请原谅我。", "犯错后立即悔改。", "安拉宽恕了穆萨 (AS)。"),
        "dua_q_musa_najjini" to DuaText("穆萨的杜阿 (AS) — 将我从压迫者手中拯救出来", "主啊，求你救我脱离那些作恶的人。", "当害怕压迫者时。", "穆萨 (AS) 离开埃及时的杜阿。"),
        "dua_q_lut_unsurni" to DuaText("Dua of Lut (AS) — 帮助反腐败者", "我的主啊，请帮助我对抗腐败的人们。", "帮助打击那些传播腐败的人。", "坚守真理的人的二重奏。"),
        "dua_q_hab_li_salihin" to DuaText("易卜拉欣的杜阿 (AS) 为正义的孩子", "我的主啊，请从义人中赐予我（一个孩子）。", "祈求正直的孩子。", "通过这个 dua Isma'il (AS) 被授予。"),
        "dua_q_wasita_kulla_shay" to DuaText("承载王座的天使杜阿", "我们的主啊，您以仁慈和知识包容万物，因此请宽恕那些悔改并遵循您道路的人，并保护他们免受地狱的惩罚。", "承载宝座的天使为信徒们制作了这个杜阿。", "背诵的目的是为了将其纳入天使的二重奏中。"),
        "dua_q_ikhwanina" to DuaText("为了我们的先辈兄弟", "我们的主，请宽恕我们和我们先于我们信仰的兄弟，不要让我们心中对那些相信的人怀有怨恨。我们的主啊，您确实仁慈且仁慈。", "为之前来的信徒和一颗清洁的心而唱的杜阿。", "为高贵的同伴 (RA) 和早期信徒而作的二重奏。"),
        "dua_q_alayka_tawakkalna" to DuaText("我们依靠你（易卜拉欣 AS）", "我们的主，我们依靠你，我们转向你，我们就归向你。我们的主，请不要让我们成为不信道者的考验并宽恕我们。我们的主啊，您确实是全能者、至睿者。", "易卜拉欣 (AS) 和他的同伴的杜阿。", "对安拉的依赖和转向他的杜阿。"),
        "dua_q_atmim_nurana" to DuaText("完善我们的光", "我们的主，为我们完善我们的光并宽恕我们。事实上，你拥有掌控一切的力量。", "复活日信徒们的杜阿。", "请求有关西拉特的光明。"),
        "dua_q_asiya_baytan" to DuaText("Dua of Asiya — 詹纳的一座房子", "我的主，请在你附近为我建造一座天堂之殿，拯救我脱离法老和他的行为，并拯救我脱离那些不法之徒。", "阿西亚的杜阿，法老的妻子。", "安拉为信徒们树立了榜样。"),
        "dua_adhan_response" to DuaText("回应宣礼", "除了安拉之外，没有任何力量和能力。", "重复宣礼员所说的话；在“Hayya 'alas-salah”和“Hayya 'alal-falah' 说这个。", "谁发自内心地回应，谁就会进入天堂。"),
        "dua_adhan_shahadah" to DuaText("穆阿津作清真言后", "我也见证，除了真主之外，没有人有权受到崇拜，独自一人，没有伙伴，穆罕默德ﷺ是他的仆人和使者。我很高兴阿拉为主，穆罕默德 ﷺ 为使者，伊斯兰教为宗教。", "在听到宣礼员的信仰见证时。", "他的罪被赦免了。"),
        "dua_istiftah_baid" to DuaText("开场杜阿：让我远离罪恶", "安拉啊，请使我远离我的罪孽，就像您使东方与西方保持距离一样。安拉啊，请净化我的罪孽，就像净化白衣上的污垢一样。安拉啊，请用水、雪和冰雹洗净我的罪孽。", "开场后的takbir（也可以说是代替Sana）。", "先知 ﷺ 在大诵和背诵之间背诵了这一点。"),
        "dua_hamdan_kathiran" to DuaText("Ruku之后受到广泛好评", "我们的主，赞美属于你——丰富、纯洁和有福的赞美。", "从 ruku 崛起后，与“Rabbana lakal-hamd”一起。", "三十多名天使竞相抢先记录下来。"),
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus（Ruku & Sujood）", "（安拉是）最荣耀、最神圣、天使和圣灵的主（吉布里勒）。", "在 ruku 和 sujood 中。", "先知 ﷺ 用 ruku 和 sujood 背诵了这一点。"),
        "dua_sujood_dhanbi_kullah" to DuaText("在Sujood：宽恕我所有的罪过", "安拉啊，请宽恕我所有的罪过——无论是小罪还是大罪、最初的罪还是最后的罪、公开的罪还是隐藏的罪。", "在苏乔德。", "顶礼是得到答复的地方。"),
        "dua_sujood_ridaka" to DuaText("随心所欲地避难", "安拉啊，我寻求你的庇护，免受你的愤怒，寻求你的宽恕，免受你的惩罚，我寻求你的庇护，免受你的惩罚。我无法完全赞美你；你就是如你所称赞的那样。", "在sujood — Aisha (RA) 听到先知ﷺ 这么说。", "先知 ﷺ 的 sujood dua。"),
        "dua_tashahhud" to DuaText("塔沙胡德 (At-Tahiyyat)", "所有言语、身体和金钱的崇拜行为都是为了真主。先知啊，愿你平安，愿真主的怜悯和祝福。愿和平降临在我们和真主的正义仆人身上。我见证，除了真主之外，没有人有权受到崇拜，我见证穆罕默德 ﷺ 是他的仆人和使者。", "每次静坐 — 由阿卜杜拉·伊本·马斯乌德 (RA) 讲述（哈乃斐派实践）。", "先知 ﷺ 将其教导为《古兰经》的章节。"),
    )
}
